let dialog=$state<HTMLDialogElement>(),wide=$state<HTMLElement>();let entered=false,previous=false,destroyed=false;let saved:HTMLElement|null=null,ancestors:HTMLElement[]=[];let doc:Document|undefined;let generation=0;
